template<std::size_t Capacity, std::size_t High, std::size_t Low>
class PendingSend {
    static_assert(0 < Low && Low < High && High <= Capacity, "watermark order");
public:
    PendingSend(std::atomic<std::size_t>& total, std::size_t limit) noexcept
        : total_(total), limit_(limit) {}
    ~PendingSend() { close(); }
    PendingSend(const PendingSend&) = delete;
    PendingSend& operator=(const PendingSend&) = delete;
    std::size_t size() const noexcept { return size_; }
    std::size_t room() const noexcept { return Capacity - size_; }
    bool paused() const noexcept { return paused_; }
    bool closed() const noexcept { return closed_; }

    // Inline byte copies cannot throw: after reservation there is no allocation.
    for (std::size_t n = 0; n < count; ++n)
        bytes_[(head_ + size_ + n) % Capacity] = data[n];
    size_ += count;
    if (size_ >= High) paused_ = true;
    return BufferResult::stored;
}

inline bool try_reserve_bytes(std::atomic<std::size_t>& used, std::size_t limit,
                              std::size_t amount, std::size_t& total) noexcept {
    std::size_t current = used.load(std::memory_order_relaxed);
    for (;;) {
        // A zero-byte request succeeds only while the counter is within limit.
        // Bounds are checked before the subtraction to avoid underflow.
        if (current > limit || amount > limit - current) {
            return false;
        }
        // `current + amount <= limit`, so the addition cannot overflow.
        if (used.compare_exchange_weak(current, current + amount,
                                       std::memory_order_relaxed,
                                       std::memory_order_relaxed)) {
            total = current + amount;  // count committed by this reservation
            return true;
        }
        // CAS refreshed `current` with the latest value; retry.
    }
}

BufferResult append(const std::uint8_t* data, std::size_t count) noexcept {
    if (closed_) return BufferResult::closed;
    if (count && !data) return BufferResult::invalid;
    if (count > room()) return BufferResult::local_limit;
    std::size_t reserved = 0;
    if (!try_reserve_bytes(total_, limit_, count, reserved))
        return BufferResult::global_limit;

template<class Sender>
FlushResult flush(Sender&& send) noexcept {
    static_assert(std::is_nothrow_invocable_r_v<SendAttempt, Sender&,
                  const std::uint8_t*, std::size_t>, "sender must be noexcept");
    if (size_ == 0) return FlushResult::empty;
    const auto contiguous = (std::min)(size_, Capacity - head_);
    const auto result = send(bytes_.data() + head_, contiguous);
    if (result.state == SendState::progress) {
        if (result.count == 0 || result.count > contiguous || result.error != 0)
            return FlushResult::invalid;
        head_ = (head_ + result.count) % Capacity;
        size_ -= result.count;
        total_.fetch_sub(result.count, std::memory_order_relaxed);
        if (size_ <= Low) paused_ = false;
        return FlushResult::progress;
    }
    if (result.count != 0) return FlushResult::invalid;
    if (result.state == SendState::error) return FlushResult::error;
    if ((result.state != SendState::would_block && result.state != SendState::interrupted) ||
        result.error != 0) return FlushResult::invalid;
    return FlushResult::waiting;
}

void close() noexcept {
    if (closed_) return;
    closed_ = true;
    total_.fetch_sub(size_, std::memory_order_relaxed);
    size_ = 0;
    head_ = 0;
    paused_ = false;
}

bool sync() {
    for (std::size_t side = 0; side < 2; ++side) {
        const bool read = !queues_[1 - side].paused() && queues_[1 - side].room() >= 16;
        const unsigned desired = (read ? static_cast<unsigned>(Read) : 0u) |
            (queues_[side].size() ? static_cast<unsigned>(Write) : 0u);
        if (desired == interests_[side]) continue;
        if (!loop_.change(ids_[side], desired)) { close(); return false; }
        const bool was_reading = (interests_[side] & Read) != 0;
        if (was_reading && !read) ++pauses_;
        if (!was_reading && read) ++resumes_;
        interests_[side] = desired;
    }
    return true;
}

// Observation preceded dispatch: another event may have paused this source.
auto& destination = queues_[1 - side];
if (!(event.readable || event.error)) return;
if (destination.paused()) {
    if (event.error) close(); // HUP/ERR can be reported even with Read disabled.
    return;
}

    std::uint8_t bytes[16];
    const auto read = try_receive(socket, bytes, sizeof(bytes));
    if (read.state == ReceiveState::would_block || read.state == ReceiveState::interrupted) return;
    if (read.state != ReceiveState::progress) { close(); return; }
    const bool was_empty = destination.size() == 0;
    if (destination.append(bytes, read.count) != BufferResult::stored) { close(); return; }
    if (was_empty) timers_.arm(ids_[1 - side], Clock::now() + stall_);
    sync();
}

if (event.writable && outbound.size()) {
    const auto result = outbound.flush([&](const std::uint8_t* data, std::size_t size) noexcept {
        return try_send(socket, data, size);
    });
    if (result == FlushResult::error || result == FlushResult::invalid) { close(); return; }
    if (result == FlushResult::progress) {
        if (outbound.size()) timers_.arm(ids_[side], Clock::now() + stall_);
        else timers_.cancel(ids_[side]);
    }
    if (!sync()) return;
}

void tick(int wait_ms = 5) {
    if (closed_) return;
    const int timer = timers_.timeout_ms(Clock::now());
    const auto batch = loop_.observe(timer < 0 ? wait_ms : (std::min)(wait_ms, timer));
    if (batch.state == PollState::error) { close(); return; }
    loop_.dispatch(batch);
    std::vector<TimerHeap::Token> due;
    timers_.expired(Clock::now(), due);
    if (!due.empty()) { ++stalls_; close(); }
}
void close() noexcept {
    if (closed_) return;
    closed_ = true;
    for (std::size_t side = 0; side < 2; ++side) {
        timers_.cancel(ids_[side]);
        if (ids_[side]) loop_.close(ids_[side]);
        queues_[side].close();
    }
}

